async function solveTask(bot) {
  await bot.exploreUntil(bot => bot.inventory.count("diamond_pickaxe") > 0 && bot.findBlock({ nearby: 10, matching: "nether_quartz_ore" }) != null);
  await bot.mineBlock(bot.findBlock({ nearby: 10, matching: "nether_quartz_ore" }));
  await bot.exploreUntil(bot => bot.findBlock({ nearby: 10, matching: "quartz_block" }) != null);
  await bot.mineBlock(bot.findBlock({ nearby: 10, matching: "quartz_block" }));
}
